"""Key handling for the record store."""


def normalize_key(raw):
    """Return the canonical form of a record key."""
    if raw is None:
        raise ValueError("key must not be None")
    return str(raw).strip().lower().replace(" ", "_")

"""Rendering helpers for the record store."""

from pkg import normalize_key


def header(title):
    return "# " + normalize_key(title)


def summarize(store, keys):
    lines = []
    for key in keys:
        lines.append("%s=%s" % (normalize_key(key), store.get(key)))
    return "\n".join(lines)

"""A tiny in-memory record store."""

from pkg import normalize_key


class Store:
    def __init__(self):
        self._items = {}

    def put(self, key, value):
        self._items[normalize_key(key)] = value

    def get(self, key):
        return self._items.get(normalize_key(key))

    def keys(self):
        return sorted(self._items)

import os
import sys

sys.dont_write_bytecode = True  # never leave a stale .pyc shadowing an edited module

import unittest

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

from pkg import canonical_key
from report import header, summarize
from store import Store


class TestCanonicalKey(unittest.TestCase):
    def test_lowercases_and_underscores(self):
        self.assertEqual(canonical_key("  Total Count "), "total_count")

    def test_rejects_none(self):
        with self.assertRaises(ValueError):
            canonical_key(None)


class TestStore(unittest.TestCase):
    def test_round_trip_is_key_insensitive(self):
        store = Store()
        store.put("Total Count", 7)
        self.assertEqual(store.get("total_count"), 7)
        self.assertEqual(store.keys(), ["total_count"])


class TestReport(unittest.TestCase):
    def test_header(self):
        self.assertEqual(header("Run Summary"), "# run_summary")

    def test_summarize(self):
        store = Store()
        store.put("A B", 1)
        self.assertEqual(summarize(store, ["A B"]), "a_b=1")


if __name__ == "__main__":
    unittest.main(verbosity=2)

